<span class="line"><span style="color:#E06C75;">    redis</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">call</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;HSET&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">reserved_key</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">order_id</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">quantity</span><span style="color:#ABB2BF;">)</span></span>
